// ── Auth: Get Token (Fetch API) ──────────────────────────────────────
const BASE_URL = "https://api.sandbox.example.com";

async function getToken(userId = "alice", role = "user") {
  const res = await fetch(`${BASE_URL}/auth/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ user_id: userId, role }),
  });

  if (!res.ok) {
    throw new Error(`Login failed: ${res.status}`);
  }

  const { data } = await res.json();
  // Store access_token in memory — never in localStorage (XSS risk)
  sessionStorage.setItem("access_token", data.access_token);
  sessionStorage.setItem("refresh_token", data.refresh_token);
  sessionStorage.setItem("user_id", data.user_id);
  return data;
}

// Usage
getToken().then(data => console.log("Token expires in:", data.expires_in, "seconds"));

