// ── Auth: Get Token (net/http) ───────────────────────────────────────
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"net/http"
)

const baseURL = "https://api.sandbox.example.com"

type loginRequest struct {
	UserID string `json:"user_id"`
	Role   string `json:"role"`    // optional: "user" | "admin"
}

type tokenPair struct {
	AccessToken  string `json:"access_token"`
	RefreshToken string `json:"refresh_token"`
	ExpiresIn    int    `json:"expires_in"`
	Role         string `json:"role"`
	UserID       string `json:"user_id"`
}

type apiResponse struct {
	Success bool      `json:"success"`
	Data    tokenPair `json:"data"`
}

func getToken(userID, role string) (*tokenPair, error) {
	body, _ := json.Marshal(loginRequest{UserID: userID, Role: role})

	resp, err := http.Post(baseURL+"/auth/login", "application/json", bytes.NewReader(body))
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("unexpected status: %d", resp.StatusCode)
	}

	var result apiResponse
	if err := json.NewDecoder(resp.Body).Decode(&result); err != nil {
		return nil, err
	}
	return &result.Data, nil
}

func main() {
	pair, err := getToken("alice", "user")
	if err != nil {
		panic(err)
	}
	fmt.Printf("Access token: %s...\n", pair.AccessToken[:20])
}

