// ── Auth: Get Token (OkHttp) ─────────────────────────────────────────
import okhttp3.*;
import org.json.JSONObject;

public class AuthExample {
    private static final String BASE_URL = "https://api.sandbox.example.com";
    private static final OkHttpClient client = new OkHttpClient();
    private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");

    public static String getToken(String userId, String role) throws Exception {
        JSONObject payload = new JSONObject();
        payload.put("user_id", userId);
        payload.put("role", role); // optional: "user" | "admin"

        RequestBody body = RequestBody.create(payload.toString(), JSON);
        Request request = new Request.Builder()
                .url(BASE_URL + "/auth/login")
                .post(body)
                .build();

        try (Response response = client.newCall(request).execute()) {
            if (!response.isSuccessful()) {
                throw new RuntimeException("Login failed: " + response.code());
            }
            JSONObject resp = new JSONObject(response.body().string());
            return resp.getJSONObject("data").getString("access_token");
        }
    }

    public static void main(String[] args) throws Exception {
        String accessToken = getToken("alice", "user");
        System.out.println("Token: " + accessToken.substring(0, 20) + "...");
    }
}

