package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"net/http"
)

type createProductRequest struct {
	Name  string  `json:"name"`
	SKU   string  `json:"sku"`
	Price float64 `json:"price"`
}

func createProduct(accessToken string, req createProductRequest) error {
	body, _ := json.Marshal(req)

	httpReq, _ := http.NewRequest(http.MethodPost, baseURL+"/api/v1/products", bytes.NewReader(body))
	httpReq.Header.Set("Content-Type", "application/json")
	httpReq.Header.Set("Authorization", "Bearer "+accessToken) // <── attach token

	resp, err := http.DefaultClient.Do(httpReq)
	if err != nil {
		return err
	}
	defer resp.Body.Close()

	if resp.StatusCode == http.StatusUnauthorized {
		return fmt.Errorf("token expired — call POST /auth/refresh")
	}
	if resp.StatusCode != http.StatusCreated && resp.StatusCode != http.StatusOK {
		return fmt.Errorf("unexpected status: %d", resp.StatusCode)
	}
	return nil
}

func main() {
	pair, _ := getToken("alice", "user") // from previous snippet
	err := createProduct(pair.AccessToken, createProductRequest{
		Name:  "Mechanical Keyboard",
		SKU:   "KB-001",
		Price: 2990.00,
	})
	if err != nil {
		panic(err)
	}
	fmt.Println("Product created!")
}

