// ── List Products (Fetch API) ────────────────────────────────────────
const BASE_URL = "https://api.sandbox.example.com";

async function listProducts(token, { limit = 10, cursor = null } = {}) {
  const params = new URLSearchParams({ limit });
  if (cursor) params.set("cursor", cursor); // append cursor for next page

  const res = await fetch(`${BASE_URL}/api/v1/products?${params}`, {
    headers: { "Authorization": `Bearer ${token}` },
  });

  if (res.status === 401) throw new Error("Token expired. Refresh it.");
  if (!res.ok) throw new Error(`HTTP ${res.status}`);

  return (await res.json()).data; // { items, next_cursor, count }
}

// Fetch all pages example
async function fetchAllProducts(token) {
  let cursor = null;
  const all = [];
  do {
    const page = await listProducts(token, { limit: 10, cursor });
    all.push(...page.items);
    cursor = page.next_cursor || null; // null when no more pages
  } while (cursor);
  return all;
}

