# ── List Products (requests) ─────────────────────────────────────────
import requests

BASE_URL = "https://api.sandbox.example.com"

def list_products(access_token: str, limit: int = 10, cursor: str = None) -> dict:
    headers = {"Authorization": f"Bearer {access_token}"}
    params  = {"limit": limit}
    if cursor:
        params["cursor"] = cursor  # for subsequent pages

    resp = requests.get(f"{BASE_URL}/api/v1/products", headers=headers, params=params, timeout=10)
    if resp.status_code == 401:
        raise Exception("Token expired. Refresh with POST /auth/refresh.")
    resp.raise_for_status()
    return resp.json()["data"]  # { items, next_cursor, count }

# Fetch all pages — cursor pagination
def fetch_all_products(access_token: str) -> list:
    all_items, cursor = [], None
    while True:
        page   = list_products(access_token, limit=10, cursor=cursor)
        all_items.extend(page["items"])
        cursor = page.get("next_cursor")  # None when last page
        if not cursor:
            break
    return all_items

products = fetch_all_products(access_token)  # access_token from get_token()
print(f"Total: {len(products)} products")

