package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
	"strconv"
)

type productListResponse struct {
	Items      []map[string]interface{} `json:"items"`
	NextCursor string                   `json:"next_cursor"`
	Count      int                      `json:"count"`
}

type listAPIResponse struct {
	Success bool                `json:"success"`
	Data    productListResponse `json:"data"`
}

func listProducts(accessToken string, limit int, cursor string) (*productListResponse, error) {
	params := url.Values{}
	params.Set("limit", strconv.Itoa(limit))
	if cursor != "" {
		params.Set("cursor", cursor) // pagination cursor
	}

	req, _ := http.NewRequest(http.MethodGet,
		baseURL+"/api/v1/products?"+params.Encode(), nil)
	req.Header.Set("Authorization", "Bearer "+accessToken) // <── attach token

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	if resp.StatusCode == http.StatusUnauthorized {
		return nil, fmt.Errorf("token expired — call POST /auth/refresh")
	}

	var result listAPIResponse
	json.NewDecoder(resp.Body).Decode(&result)
	return &result.Data, nil
}

func main() {
	pair, _ := getToken("alice", "user")
	page, err := listProducts(pair.AccessToken, 10, "")
	if err != nil {
		panic(err)
	}
	fmt.Printf("Got %d products, next_cursor: %s\n", page.Count, page.NextCursor)
}

