  final all = <dynamic>[];
  String? cursor;
  do {
    final page = await listProducts(accessToken: accessToken, cursor: cursor);
    all.addAll(page['items'] as List);
    cursor = page['next_cursor'] as String?;
  } while (cursor != null);
  return all;
